def add_demo_key_dates(apps, schema_editor):
    Project = apps.get_model("projects", "Project")
    ProjectKeyDate = apps.get_model("projects", "ProjectKeyDate")
    projects = {p.name: p for p in Project.objects.filter(name__in=[k[0] for k in DEMO_KEY_DATES])}
